// news-image-20261124: writes the 24 November 2026 world-news front page.
// The image is embedded below as base64 PNG data (drawn in this session
// with a Pillow script: 46 verified stories, masthead, UTC timeline,
// dotted world map, DATE CHECK box and footer). No network is used.
// Output is fully deterministic: the same bytes on every run.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const IMAGE_B64 =
  "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR || "/output";
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "entry.png"), Buffer.from(IMAGE_B64, "base64"));
